INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (151, 176, 'Acrylic acid coating film', '../upload/image/20180826/20180826131109_71020.jpg', '<p></p><p>Acrylic acid coating film</p> <p>1. ACRYLIC ACID COATING BOPP FILM<br/> Acrylic coated BOPP film on one or two side(s) with a detailed description of:<br/> BOPP acrylic films were based on BOPP film, coated on one or two side(s) with acrylic. Wide range of uses, especially suitable for the packaging of biscuits and other snack products ; suitable for food boxes, medicine boxes, perfume boxes, cosmetic boxes. <br/> Main performance for Crylic acid coating film:<br/> a.) excellent packaging adaptability, low coefficient of friction of the coating and stability; <br/> b.) excellent low-temperature heat sealing properties, outstanding transparency properties; <br/> c.) applicable to various ink printing, including water-based inks<br/> Thickness: 20 30 Microns...<br/> Width: 120-1500MM Length: 200-4000M Inner core:1" 2" 3" 6". <br/> 2. ACRYLIC ACID COATING BOPET FILM<br/> Acrylic coated BOPET film on one or two side(s) with a detailed description of:<br/> The film is PET acrylic coating film to the substrate, the single-sided coating of acrylic. Particularly suitable for the packaging of biscuits and other snack products Bao-Xiang; also suitable for food boxes, medicine boxes, perfume boxes, cosmetic boxes. <br/> Main performance for Acrylic acid coating film<br/> a.) excellent packaging adaptability, low coefficient of friction of the coating and stability; <br/> b.) excellent low-temperature heat sealing properties, outstanding transparency properties; <br/> c.) applicable to various ink printing, including water-based inks.<br/> Thickness: 14.1 17.1 Microns...<br/> Width: 120-1500MM Length: 200-4000M Inner core:1" 2" 3" 6".</p>', '2026-09-06 20:58:45');
